        angle = math.radians(struct.unpack("f", struct.pack("f", geometry.get("rotation_degrees", 0.0)))[0]) # TEST-SUPPORT: SHIELD-BAKE-012 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_cli_write_check_preserves_other_fields, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        cosine, sine = math.cos(angle), math.sin(angle) # TEST-SUPPORT: SHIELD-BAKE-013 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_cli_write_check_preserves_other_fields, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        radii = geometry.get("radii", [geometry.get("radius"), geometry.get("radius")]) # TEST-SUPPORT: SHIELD-BAKE-014 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_cli_write_check_preserves_other_fields, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        for value in geometry["center"] + radii + [geometry.get("rotation_degrees", 0.0)]: # TEST-SUPPORT: SHIELD-BAKE-301 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_cli_write_check_preserves_other_fields, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
            self.assertEqual(value, round(value, 1)) # TEST-SUPPORT: SHIELD-BAKE-302 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_cli_write_check_preserves_other_fields, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
            if value == 0: # TEST-SUPPORT: SHIELD-BAKE-303 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_cli_write_check_preserves_other_fields, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
                self.assertEqual(math.copysign(1, value), 1) # TEST-SUPPORT: SHIELD-BAKE-304 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_cli_write_check_preserves_other_fields, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        radii = [struct.unpack("f", struct.pack("f", value))[0] for value in radii] # TEST-SUPPORT: SHIELD-BAKE-203 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_cli_write_check_preserves_other_fields, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        for x, y in points: # TEST-SUPPORT: SHIELD-BAKE-015 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_cli_write_check_preserves_other_fields, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
            dx, dy = x - center[0], y - center[1] # TEST-SUPPORT: SHIELD-BAKE-016 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_cli_write_check_preserves_other_fields, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
            along = dx * cosine + dy * sine # TEST-SUPPORT: SHIELD-BAKE-017 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_cli_write_check_preserves_other_fields, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
            across = -dx * sine + dy * cosine # TEST-SUPPORT: SHIELD-BAKE-018 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_cli_write_check_preserves_other_fields, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
            self.assertLessEqual((along / radii[0]) ** 2 + (across / radii[1]) ** 2, 1.0) # TEST-SUPPORT: SHIELD-BAKE-019 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_cli_write_check_preserves_other_fields, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside

