        command = [sys.executable, "-B", str(Path(baker.__file__).resolve()), "--ships", str(ships), *arguments] # TEST-SUPPORT: SHIELD-BAKE-021 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_cli_write_check_preserves_other_fields, tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_transparent_input_is_atomic_and_selection_isolated
