        self.assertAlmostEqual(circle["center"][0], 2.0, places=5) # TEST-SUPPORT: SHIELD-BAKE-035 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
        self.assertAlmostEqual(circle["center"][1], -3.0, places=5) # TEST-SUPPORT: SHIELD-BAKE-036 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
        self.assertEqual(circle["radius"], 1.5) # TEST-SUPPORT: SHIELD-BAKE-037 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
        self.assert_contains(yaml.safe_load(yaml.safe_dump(circle)), square) # TEST-SUPPORT: SHIELD-BAKE-038 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
