        rectangle = [(5 + x * math.cos(angle) - y * math.sin(angle), -7 + x * math.sin(angle) + y * math.cos(angle)) for x in (-4, 4) for y in (-1, 1)] # TEST-SUPPORT: SHIELD-BAKE-040 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
        ellipse = baker.fit_shield_geometry(rectangle) # TEST-SUPPORT: SHIELD-BAKE-041 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
        self.assertEqual(ellipse["shape"], "ellipse") # TEST-SUPPORT: SHIELD-BAKE-042 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
        self.assertAlmostEqual(ellipse["center"][0], 5.0, places=4) # TEST-SUPPORT: SHIELD-BAKE-043 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
        self.assertAlmostEqual(ellipse["center"][1], -7.0, places=4) # TEST-SUPPORT: SHIELD-BAKE-044 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
        self.assertAlmostEqual(ellipse["radii"][0], 4 * math.sqrt(2), delta=0.2) # TEST-SUPPORT: SHIELD-BAKE-045 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
        self.assertAlmostEqual(ellipse["radii"][1], math.sqrt(2), delta=0.2) # TEST-SUPPORT: SHIELD-BAKE-046 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
        self.assertAlmostEqual(ellipse["rotation_degrees"] % 180, 30, places=3) # TEST-SUPPORT: SHIELD-BAKE-047 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
        self.assert_contains(yaml.safe_load(yaml.safe_dump(ellipse)), rectangle) # TEST-SUPPORT: SHIELD-BAKE-048 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
        elongated_corners = [(x, y) for x in (-100, 100) for y in (-1, 1)] # TEST-SUPPORT: SHIELD-BAKE-401 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
        elongated = yaml.safe_load(yaml.safe_dump(baker.fit_shield_geometry(elongated_corners))) # TEST-SUPPORT: SHIELD-BAKE-402 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
        self.assertEqual(elongated["shape"], "ellipse") # TEST-SUPPORT: SHIELD-BAKE-403 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_known_shapes_and_serialized_containment
