    def test_rounding_keeps_rotated_shifted_silhouette_inside(self): # TEST-SUPPORT: SHIELD-BAKE-305 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        angle = math.radians(30.04) # TEST-SUPPORT: SHIELD-BAKE-306 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        corners = [(-0.04 + x * math.cos(angle) - y * math.sin(angle), 0.04 + x * math.sin(angle) + y * math.cos(angle)) for x in (-4.04 / math.sqrt(2), 4.04 / math.sqrt(2)) for y in (-1.04 / math.sqrt(2), 1.04 / math.sqrt(2))] # TEST-SUPPORT: SHIELD-BAKE-307 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        naive = {"shape": "ellipse", "center": [0.0, 0.0], "radii": [4.0, 1.0], "rotation_degrees": 30.0} # TEST-SUPPORT: SHIELD-BAKE-308 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        with self.assertRaises(AssertionError): # TEST-SUPPORT: SHIELD-BAKE-309 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
            self.assert_contains(naive, corners) # TEST-SUPPORT: SHIELD-BAKE-310 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        geometry = yaml.safe_load(yaml.safe_dump(baker.fit_shield_geometry(corners))) # TEST-SUPPORT: SHIELD-BAKE-311 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        self.assertEqual(geometry["shape"], "ellipse") # TEST-SUPPORT: SHIELD-BAKE-312 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        self.assertEqual(geometry["center"], [0.0, 0.0]) # TEST-SUPPORT: SHIELD-BAKE-313 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        self.assertEqual(geometry["rotation_degrees"], 30.0) # TEST-SUPPORT: SHIELD-BAKE-314 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        self.assertGreater(geometry["radii"][0] * geometry["radii"][1], 4.0) # TEST-SUPPORT: SHIELD-BAKE-315 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        self.assertAlmostEqual(geometry["radii"][0], 4.04, delta=0.3) # TEST-SUPPORT: SHIELD-BAKE-316 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        self.assertAlmostEqual(geometry["radii"][1], 1.04, delta=0.3) # TEST-SUPPORT: SHIELD-BAKE-317 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside
        self.assert_contains(geometry, corners) # TEST-SUPPORT: SHIELD-BAKE-318 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_rounding_keeps_rotated_shifted_silhouette_inside

    def test_alpha_pixel_corners(self): # TEST-SUPPORT: SHIELD-BAKE-049 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners
        with Image.new("RGBA", (8, 6), (255, 0, 0, 0)) as image: # TEST-SUPPORT: SHIELD-BAKE-050 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners
            image.putpixel((1, 2), (0, 255, 0, 1)) # TEST-SUPPORT: SHIELD-BAKE-051 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners
            image.putpixel((6, 4), (0, 0, 255, 255)) # TEST-SUPPORT: SHIELD-BAKE-052 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners
            hull = baker.silhouette_hull(image) # TEST-SUPPORT: SHIELD-BAKE-053 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners
            self.assertEqual(min(point[0] for point in hull), -3) # TEST-SUPPORT: SHIELD-BAKE-054 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners
            self.assertEqual(max(point[0] for point in hull), 3) # TEST-SUPPORT: SHIELD-BAKE-055 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners
            self.assertEqual(min(point[1] for point in hull), -1) # TEST-SUPPORT: SHIELD-BAKE-056 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners
            self.assertEqual(max(point[1] for point in hull), 2) # TEST-SUPPORT: SHIELD-BAKE-057 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners
            corners = [(-3, -1), (-2, -1), (-3, 0), (-2, 0), (2, 1), (3, 1), (2, 2), (3, 2)] # TEST-SUPPORT: SHIELD-BAKE-058 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners
            serialized = yaml.safe_load(yaml.safe_dump(baker.fit_shield_geometry(hull))) # TEST-SUPPORT: SHIELD-BAKE-059 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners
            self.assert_contains(serialized, corners) # TEST-SUPPORT: SHIELD-BAKE-060 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners
            threshold_hull = baker.silhouette_hull(image, alpha_threshold=255) # TEST-SUPPORT: SHIELD-BAKE-061 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners
            self.assertEqual(set(map(tuple, threshold_hull)), {(2, 1), (3, 1), (2, 2), (3, 2)}) # TEST-SUPPORT: SHIELD-BAKE-062 | Tests: tools.shield_geometry.test_bake_shield_geometry.ShieldGeometryBakerTests.test_alpha_pixel_corners

